fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // Handle edge cases: empty array or single element
    if n <= 1 {
        return numbers;
    }
    
    // Calculate the size of the result: 2*n - 1
    let result_len = 2 * n - 1;
    let mut result = Vec::with_capacity(result_len);
    
    // Build the result array
    for (i, &num) in numbers.iter().enumerate() {
        // Add the current number
        result.push(num);
        
        // Add delimiter after each element except the last one
        if i < n - 1 {
            result.push(delimiter);
        }
    }
    
    result
}